content.query:
let created = SecurityIncident | where Severity in ({Severity}) | summarize arg_max(TimeGenerated, *) by IncidentNumber | where CreatedTime between ({TimeRange:start} .. {TimeRange:end}) | summarize Count = count() by bin(CreatedTime, 1d) | extend Series = "Created" | project Day = CreatedTime, Count, Series;
let closed = SecurityIncident | where Severity in ({Severity}) | summarize arg_max(TimeGenerated, *) by IncidentNumber | where isnotempty(ClosedTime) | where ClosedTime between ({TimeRange:start} .. {TimeRange:end}) | summarize Count = count() by bin(ClosedTime, 1d) | extend Series = "Closed" | project Day = ClosedTime, Count, Series;
union created, closed
| order by Day asc
